(function () {
  'use strict';

  if (typeof window.DOMPurify === 'undefined') {
    throw new Error('security.js: DOMPurify no está disponible. Verifica la carga del CDN.');
  }

  var PURIFY_CONFIG = {
    ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'a', 'p', 'br', 'ul', 'ol', 'li', 'span', 'h2', 'h3', 'h4'],
    ALLOWED_ATTR: ['href', 'title', 'target', 'rel'],
    ALLOW_DATA_ATTR: false,
    FORCE_BODY: false
  };

  function sanitize(dirtyHTML) {
    if (typeof dirtyHTML !== 'string' || dirtyHTML === '') {
      return '';
    }
    return window.DOMPurify.sanitize(dirtyHTML, PURIFY_CONFIG);
  }

  function setHTML(element, dirtyHTML) {
    if (element === null || !(element instanceof Element)) {
      console.warn('security.js: setHTML recibió un elemento inválido.');
      return;
    }
    element.innerHTML = sanitize(dirtyHTML);
  }

  function escapeText(text) {
    if (typeof text !== 'string') {
      return '';
    }
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;');
  }

  window.Security = {
    setHTML: setHTML,
    escapeText: escapeText
  };

}());

// assets/js/analytics.js
// Módulo de consentimiento de cookies y carga condicional de Google Analytics.
// Sin módulos ES6, sin clases, sin librerías externas.

function _hideBanner() {
  var banner = document.getElementById('cookie-banner');
  if (banner) {
    banner.setAttribute('hidden', '');
    banner.classList.add('is-hidden');
  }
}

function _loadGA() {
  var script = document.createElement('script');
  script.async = true;
  script.src = 'https://www.googletagmanager.com/gtag/js?id=GA_MEASUREMENT_ID';
  document.head.appendChild(script);

  window.dataLayer = window.dataLayer || [];
  function gtag() { dataLayer.push(arguments); }
  window.gtag = gtag;
  gtag('js', new Date());
  gtag('config', 'GA_MEASUREMENT_ID');
}

function _onAccept() {
  localStorage.setItem('cookie_consent', 'accepted');
  _hideBanner();
  document.body.classList.add('is-accepted');
  _loadGA();
}

function _onReject() {
  localStorage.setItem('cookie_consent', 'rejected');
  _hideBanner();
}

function initAnalytics() {
  var consent = localStorage.getItem('cookie_consent');

  if (consent === 'accepted') {
    _hideBanner();
    document.body.classList.add('is-accepted');
    _loadGA();
    return;
  }

  if (consent === 'rejected') {
    _hideBanner();
    return;
  }

  var acceptBtn = document.getElementById('cookie-accept-btn');
  var rejectBtn = document.getElementById('cookie-reject-btn');

  if (acceptBtn) {
    acceptBtn.addEventListener('click', _onAccept);
  }

  if (rejectBtn) {
    rejectBtn.addEventListener('click', _onReject);
  }
}

const SECTIONS = ['home', 'historias', 'noticias'];
const DEFAULT_SECTION = 'home';

function _getSectionFromHash() {
  var hash = window.location.hash.replace('#', '');
  if (SECTIONS.indexOf(hash) !== -1) {
    return hash;
  }
  return DEFAULT_SECTION;
}

function _hideAllSections() {
  var elements = document.querySelectorAll('[data-section]');
  for (var i = 0; i < elements.length; i++) {
    elements[i].setAttribute('hidden', '');
    elements[i].classList.add('is-hidden');
  }
}

function _deactivateAllNavLinks() {
  var links = document.querySelectorAll('.nav-link');
  for (var i = 0; i < links.length; i++) {
    links[i].classList.remove('is-active');
  }
}

function _closeMobileMenu() {
  var navLinks = document.getElementById('nav-links');
  if (navLinks) {
    navLinks.classList.add('is-hidden');
  }
}

function _showSection(sectionName) {
  _hideAllSections();
  _deactivateAllNavLinks();

  var sectionEl = document.querySelector('[data-section="' + sectionName + '"]');
  if (!sectionEl) {
    return;
  }

  sectionEl.removeAttribute('hidden');
  sectionEl.classList.remove('is-hidden');

  var navLink = document.querySelector('.nav-link[data-section="' + sectionName + '"]');
  if (navLink) {
    navLink.classList.add('is-active');
  }

  _closeMobileMenu();
}

function _initMobileMenu() {
  var toggle = document.getElementById('nav-toggle');
  if (!toggle) {
    return;
  }

  toggle.addEventListener('click', function () {
    var navLinks = document.getElementById('nav-links');
    if (navLinks) {
      navLinks.classList.toggle('is-hidden');
    }
  });

  document.addEventListener('click', function (event) {
    var mainNav = document.getElementById('main-nav');
    if (mainNav && !mainNav.contains(event.target)) {
      _closeMobileMenu();
    }
  });
}

function _initNavLinks() {
  var links = document.querySelectorAll('.nav-link');
  for (var i = 0; i < links.length; i++) {
    links[i].addEventListener('click', function (event) {
      event.preventDefault();
      var sectionName = this.getAttribute('data-section');
      if (sectionName) {
        window.location.hash = '#' + sectionName;
        _showSection(sectionName);
      }
    });
  }
}

function _initRouter() {
  window.addEventListener('hashchange', function () {
    _showSection(_getSectionFromHash());
  });

  _showSection(_getSectionFromHash());
}

function init() {
  _initMobileMenu();
  _initNavLinks();
  _initRouter();
  initAnalytics();
}

document.addEventListener('DOMContentLoaded', init);

* {
  box-sizing: border-box;
}

*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --color-primary: #2563eb;
  --color-primary-dark: #1d4ed8;
  --color-secondary: #64748b;
  --color-accent: #0ea5e9;
  --color-bg: #ffffff;
  --color-bg-alt: #f8fafc;
  --color-text: #1e293b;
  --color-text-muted: #64748b;
  --color-border: #e2e8f0;
  --color-error: #dc2626;
  --color-success: #16a34a;

  --font-family-base: system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.875rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 2rem;
  --font-size-4xl: 2.5rem;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;
  --line-height-base: 1.6;
  --line-height-tight: 1.25;

  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-12: 3rem;
  --space-16: 4rem;

  --max-width: 1200px;
  --nav-height: 4rem;
  --border-radius: 0.5rem;
  --border-radius-sm: 0.25rem;

  --bp-sm: 640px;
  --bp-md: 768px;
  --bp-lg: 1024px;
  --bp-xl: 1280px;

  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);

  --transition-base: 150ms ease-in-out;
}

html {
  font-size: 100%;
}

body {
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
  color: var(--color-text);
  background-color: var(--color-bg);
  margin: 0;
  padding: 0;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--color-primary);
  text-decoration: none;
}

a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

ul,
ol {
  list-style: none;
  margin: 0;
  padding: 0;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  line-height: var(--line-height-tight);
  font-weight: var(--font-weight-bold);
  margin: 0 0 var(--space-4) 0;
}

p {
  margin: 0 0 var(--space-4) 0;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
}

/* CONTRATO: Fuente única de verdad para ocultar elementos */
.is-hidden {
  display: none !important;
}

/* CONTRATO: Refuerzo del atributo HTML nativo */
[hidden] {
  display: none !important;
}

.wrapper {
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--space-4);
}

@media (min-width: 768px) {
  .wrapper {
    padding-inline: var(--space-8);
  }
}

main {
  padding-top: var(--nav-height);
  min-height: calc(100vh - var(--nav-height));
}

#main-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background-color: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

#main-nav .wrapper {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.nav-brand {
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  color: var(--color-primary);
  text-decoration: none;
}

.nav-brand:hover {
  color: var(--color-primary-dark);
  text-decoration: none;
}

#nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-6);
}

.nav-link {
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-medium);
  color: var(--color-text);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--border-radius-sm);
  transition: color var(--transition-base), background-color var(--transition-base);
  text-decoration: none;
}

.nav-link:hover {
  color: var(--color-primary);
  background-color: var(--color-bg-alt);
  text-decoration: none;
}

/* CONTRATO: Estado activo en navegación — usado por main.js */
.nav-link.is-active {
  color: var(--color-primary);
  background-color: var(--color-bg-alt);
  font-weight: var(--font-weight-bold);
}

#nav-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 2.5rem;
  height: 2.5rem;
  padding: var(--space-2);
  border-radius: var(--border-radius-sm);
  color: var(--color-text);
  transition: background-color var(--transition-base), color var(--transition-base);
}

#nav-toggle:hover {
  background-color: var(--color-bg-alt);
  color: var(--color-primary);
}

@media (max-width: 767px) {
  #nav-toggle {
    display: flex;
  }

  #nav-links {
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    background-color: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    box-shadow: var(--shadow-md);
    padding: var(--space-2) var(--space-4);
  }

  #nav-links.is-hidden {
    display: none !important;
  }

  .nav-link {
    padding: var(--space-3) var(--space-4);
    border-radius: var(--border-radius-sm);
  }
}

section {
  padding-block: var(--space-12);
}

.section-header {
  margin-bottom: var(--space-8);
}

.section-header h2 {
  font-size: var(--font-size-3xl);
  color: var(--color-text);
  margin-bottom: var(--space-2);
}

.section-intro {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  max-width: 60ch;
  margin-bottom: 0;
}

.section-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
}

@media (min-width: 640px) {
  .section-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .section-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

footer {
  background-color: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  padding-block: var(--space-8);
  color: var(--color-text-muted);
  font-size: var(--font-size-sm);
  text-align: center;
}

.form-input {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  color: var(--color-text);
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-sm);
  transition: border-color var(--transition-base), box-shadow var(--transition-base);
  outline: none;
}

.form-input:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgb(37 99 235 / 0.15);
}

.form-input.is-error {
  border-color: var(--color-error);
  box-shadow: 0 0 0 3px rgb(220 38 38 / 0.15);
}

.form-error-msg {
  display: block;
  margin-top: var(--space-1);
  font-size: var(--font-size-sm);
  color: var(--color-error);
}

/* components.css — Estilos de componentes: Cards, FAQ, Cookie Banner */
/* PROYECTO: XP-14 | DEPENDE DE: assets/css/styles.css (cargado antes) */
/* PROHIBIDO: redefinir .is-hidden, .wrapper, #main-nav o cualquier selector de styles.css */

/* ============================================================
   COMPONENTE: CARD
   ============================================================ */

.card {
  display: flex;
  flex-direction: column;
  background: #ffffff;
  border: 1px solid #e8e8e8;
  border-radius: 8px;
  padding: 1.25rem;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
  transition: box-shadow 0.2s ease;
}

.card:hover {
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.13);
}

.card-tag {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #0057b8;
  margin-bottom: 0.4rem;
}

.card-title {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: #1a1a1a;
  text-decoration: none;
}

.card-body {
  font-size: 0.9rem;
  line-height: 1.6;
  color: #444444;
  flex-grow: 1;
}

.card-meta {
  font-size: 0.78rem;
  color: #777777;
  margin-top: 0.75rem;
}

.card-link {
  display: inline-block;
  margin-top: 1rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: #0057b8;
  text-decoration: none;
}

.card-link:hover {
  text-decoration: underline;
}

/* ============================================================
   COMPONENTE: FAQ
   ============================================================ */

.faq-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.faq-item {
  border-bottom: 1px solid #e0e0e0;
}

.faq-question {
  display: block;
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 1rem 0;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  color: #1a1a1a;
  appearance: none;
  -webkit-appearance: none;
}

.faq-question::after {
  content: '+';
  float: right;
  font-weight: 700;
  font-size: 1.1rem;
  line-height: 1;
  color: #0057b8;
}

.faq-question:focus-visible {
  outline: 2px solid #0057b8;
  outline-offset: 2px;
}

.faq-answer {
  padding: 0 0 1rem 0;
  font-size: 0.9rem;
  line-height: 1.7;
  color: #444444;
  border-top: 1px solid #f0f0f0;
}

.faq-item.is-open .faq-question::after {
  content: '−';
}

/* ============================================================
   COMPONENTE: COOKIE BANNER
   ============================================================ */

.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(20, 20, 20, 0.95);
  color: #ffffff;
  padding: 1rem 1.5rem;
  z-index: 1000;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}

.cookie-banner__text {
  flex: 1 1 60%;
  font-size: 0.85rem;
  line-height: 1.5;
  color: #f0f0f0;
}

.cookie-banner__actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.cookie-btn {
  padding: 0.5rem 1.1rem;
  border-radius: 4px;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid #ffffff;
  background: transparent;
  color: #ffffff;
  transition: background 0.15s ease;
}

.cookie-btn:hover {
  background: rgba(255, 255, 255, 0.15);
}

.cookie-btn--accept {
  background: #0057b8;
  border-color: #0057b8;
  color: #ffffff;
}

.cookie-btn--accept:hover {
  background: #004099;
  border-color: #004099;
}

/* ============================================================
   FALLBACK: Ocultar banner si body tiene .is-accepted
   (analytics.js agrega esta clase al aceptar cookies)
   ============================================================ */

body.is-accepted #cookie-banner {
  display: none;
}
